mapper.update:
update articles
user_id = #{userId}, title = #{title}, content = #{content}, cover_image = #{coverImage}, created_at = #{createdAt}, updated_at = #{updatedAt}, status = #{status}, category_id = #{categoryId}, view_count = #{viewCount}, comment_count = #{commentCount}, like_count = #{likeCount}
where article_id = #{articleId}

mapper.select:
SELECT a.article_id, a.user_id, a.title, a.content, a.cover_image, a.created_at, a.updated_at, a.view_count, a.comment_count, a.like_count, a.status, a.category_id FROM articles a WHERE a.status = #{statusPublish} AND a.user_id != #{userId} AND a.updated_at >= #{startTime}
AND a.category_id IN
#{categoryId}
AND EXISTS ( SELECT 1 FROM article_tags t INNER JOIN tags tg ON t.tag_id = tg.tag_id WHERE t.article_id = a.article_id AND tg.tag_name IN
#{tag}
)
ORDER BY a.updated_at DESC LIMIT #{recallLimit}
